from public.question_packs pack
cross join (values
  ('amethyst-geode-underground', 'Amethyst geodes are usually discovered in what kind of place?', 'Underground', 'Inside a swamp hut', 'On top of a village', 'In the End sky', 0, 'Amethyst geodes generate underground and must be found while exploring below the surface.', 1, false),
