  ('fence-stops-animal-escape', 'Which block is often used to keep animals inside a pen?', 'Banner', 'Chest', 'Torch', 'Fence', 3, 'Fences are a common pen block because animals do not simply walk through them.', 17, false),
  ('ladder-climbs-wall', 'Which block helps you climb straight up a wall?', 'Carpet', 'Ladder', 'Trapdoor', 'Fence', 1, 'Ladders attach to blocks and make a quick vertical path for players.', 18, true),
  ('slab-is-half-block', 'Which building piece is half as tall as a full block?', 'Pane', 'Slab', 'Wall', 'Torch', 1, 'Slabs are great for floors, roofs, and smoother shapes because they are half-height blocks.', 19, true),
  ('trapdoor-covers-hole', 'What hinged block is useful for covering a small floor opening?', 'Pressure Plate', 'Ladder', 'Sign', 'Trapdoor', 3, 'Trapdoors open and close over one-block spaces, making them useful for floors and ceilings.', 20, false),
  ('charcoal-works-for-torches', 'If a player has no coal yet, what can still be used in a torch recipe?', 'Charcoal', 'Flint', 'Ash', 'Iron Nugget', 0, 'Charcoal works like coal in torch recipes and can be made by smelting wood.', 21, false),
