  ('golden-apple-gives-extra-hearts', 'During a dangerous fight, which food can give extra Absorption hearts?', 'Bread', 'Cookie', 'Golden Apple', 'Melon Slice', 2, 'Golden apples grant helpful survival effects, including extra Absorption hearts.', 108, false),
  ('potion-of-healing-restores-health', 'If your hearts are low mid-battle, which potion restores health immediately?', 'Bottle o'' Enchanting', 'Potion of Healing', 'Potion of Water Breathing', 'Potion of Swiftness', 1, 'A Potion of Healing restores health right away, which can save a fight.', 109, false),
