  ('dragon-egg-appears-after-fight', 'After the dragon is defeated, which rare trophy block appears on the exit portal?', 'Beacon', 'Dragon Egg', 'Conduit', 'Nether Star', 1, 'A Dragon Egg appears after the Ender Dragon is defeated.', 112, false),
