  ('crying-obsidian-crafts-anchor', 'For crafting a respawn anchor, which purple block is required?', 'Crying Obsidian', 'Netherrack', 'Smooth Stone', 'End Stone', 0, 'Crying Obsidian is a key ingredient in the respawn anchor recipe.', 115, false),
  ('warped-fungus-scares-hoglins', 'To keep hoglins away from a path or camp, which fungus item can be useful?', 'Crimson Fungus', 'Glow Lichen', 'Red Mushroom', 'Warped Fungus', 3, 'Hoglins are afraid of warped fungus, which can help players stay safer in the Nether.', 116, false),
  ('blue-ice-makes-fast-boat-road', 'For extremely fast boat travel tunnels, which slippery block is often used?', 'Cobblestone', 'Sand', 'Blue Ice', 'Wool', 2, 'Blue ice is very slippery and is used in high-speed boat paths, including in the Nether.', 117, false),
  ('repeater-adds-redstone-delay', 'Clicked through several settings, which component can add delay to a redstone signal?', 'Bell', 'Repeater', 'Lectern', 'Comparator', 1, 'Repeaters can refresh signals and also add adjustable delay.', 118, false),
  ('target-block-rewards-accurate-hit', 'Hit near the bullseye, which block outputs a stronger signal for better aim?', 'Piston', 'Target Block', 'Button', 'Pressure Plate', 1, 'A target block outputs stronger redstone power when hit closer to the center.', 119, false),
  ('daylight-sensor-reads-sky-light', 'Watching the sun above, which sensor block can power day-and-night circuits?', 'Tripwire Hook', 'Stonecutter', 'Observer', 'Daylight Sensor', 3, 'Daylight sensors measure sky light and are useful for automatic day/night circuits.', 120, false)
) as v(content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active)
where pack.slug = 'minecraft-en-hard'
on conflict (pack_id, content_id) do update set
  prompt = excluded.prompt,
  option_a = excluded.option_a,
  option_b = excluded.option_b,
  option_c = excluded.option_c,
  option_d = excluded.option_d,
  correct_option = excluded.correct_option,
  explanation = excluded.explanation,
  sort_order = excluded.sort_order,
  is_active = excluded.is_active;

insert into public.question_packs (category_id, locale, age_band, difficulty, title, slug, is_active)
select id, 'ru', '8-12', 'easy', 'MineMind ru easy', 'minecraft-ru-easy', true
from public.quiz_categories
where slug = 'minecraft'
on conflict (slug) do update set is_active = true, title = excluded.title;

insert into public.questions (pack_id, content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active)
select pack.id, v.content_id, v.prompt, v.option_a, v.option_b, v.option_c, v.option_d, v.correct_option, v.explanation, v.sort_order, v.is_active
from public.question_packs pack
cross join (values
  ('badlands-has-terracotta', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. Класичним знаком якого біома є теракотові пагорби? За цією ситуацією визнач правильну місцевість або споруду.', 'Болото', 'Рівнини', 'Безплідні землі', 'Засніжені рівнини', 2, 'Безплідні землі легко впізнати за шарами теракоти та рельєфом, схожим на месу. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 1, false),
  ('bamboo-jungle-has-bamboo', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом найімовірніше заповнений бамбуком? За цією ситуацією визнач правильну місцевість або споруду.', 'Бамбукові джунглі', 'Замерзлий океан', 'Темні глибини', 'Рівнини', 0, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 2, false),
  ('beach-is-sandy-shore', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом зазвичай утворює піщану смугу вздовж океану? За цією ситуацією визнач правильну місцевість або споруду.', 'Меса', 'Пляж', 'Лука', 'Річка', 1, 'Пляжі зазвичай утворюють піщані береги вздовж океанів та інших великих водойм. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 3, false),
  ('cherry-grove-has-pink-trees', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом виділяється рожевими вишневими деревами? За цією ситуацією визнач правильну місцевість або споруду.', 'Незерська пустка', 'Болото', 'Вишневий гай', 'Скелястий берег', 2, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 4, false),
  ('desert-has-no-rain', 'В каком жарком биоме не идёт дождь?', 'Равнины', 'Река', 'Лес', 'Пустыня', 3, 'Пустыни остаются сухими, поэтому обычного дождя там не бывает.', 5, true),
  ('jungle-has-vines', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Де гравець знайде високі дерева та багато ліан? За цією ситуацією визнач правильну місцевість або споруду.', 'Пустеля', 'Замерзлий океан', 'Джунглі', 'Грибні поля', 2, 'Джунглі відомі високими деревами, густим листям і великою кількістю ліан. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 6, false),
  ('mushroom-fields-has-giant-mushrooms', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом відомий гігантськими грибами замість звичайних дерев? За цією ситуацією визнач правильну місцевість або споруду.', 'Засніжені рівнини', 'Грибні поля', 'Савана', 'Бамбукові джунглі', 1, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 7, false),
  ('ocean-mostly-water', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. Якщо біом здебільшого складається з відкритих водойм, яким біомом він, імовірно, буде? За цією ситуацією визнач правильну місцевість або споруду.', 'Савана', 'Океан', 'Тайга', 'Безплідні землі', 1, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 8, false),
  ('plains-open-grassland', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом варто шукати гравцеві, який хоче широкі відкриті луки? За цією ситуацією визнач правильну місцевість або споруду.', 'Темні глибини', 'Базальтові дельти', 'Вишневий гай', 'Рівнини', 3, 'Рівнини відкриті й порослі травою, тому там зручно будувати й пересуватися. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 9, false),
  ('river-cuts-through-land', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом часто виглядає як звивиста смуга води, що прорізає суходіл? За цією ситуацією визнач правильну місцевість або споруду.', 'Річка', 'Гай', 'Пустеля', 'Грибні поля', 0, 'Річки тягнуться довгими водними руслами крізь інші ділянки звичайного світу. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 10, false),
  ('savanna-has-acacia-trees', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Де гравець найчастіше очікує знайти дерева акації? За цією ситуацією визнач правильну місцевість або споруду.', 'Савана', 'Темний ліс', 'Замерзла річка', 'Грибні поля', 0, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 11, false),
  ('snowy-plains-has-snow', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом зазвичай покритий снігом? За цією ситуацією визнач правильну місцевість або споруду.', 'Засніжені рівнини', 'Мангрове болото', 'Джунглі', 'Пустеля', 0, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 12, false),
  ('swamp-has-lily-pads', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. У записнику гравця є така польова підказка: Який біом славиться мілководдям і багатьма лататтями? За цією ситуацією визнач правильну місцевість або споруду.', 'Безплідні землі', 'Болото', 'Савана', 'Засніжені рівнини', 1, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 13, false),
  ('taiga-has-spruce', 'Ти читаєш ландшафт під час подорожі й маєш упізнати біом не за назвою, а за ознаками місцевості. Які дерева особливо поширені в тайговому біомі? За цією ситуацією визнач правильну місцевість або споруду.', 'Акація', 'Мангровий ліс', 'Ялина', 'Вишня', 2, 'Ознаки місцевості, рельєф і типові ресурси ведуть саме до цього вибору. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 14, false),
  ('village-has-villagers', 'В какой структуре часто есть жители, кровати и поля с культурами?', 'Кораблекрушение', 'Деревня', 'Разрушенный портал', 'Заброшенная шахта', 1, 'Деревни полезно находить в начале, потому что там часто есть укрытие, еда и торговля.', 15, true),
  ('cobblestone-from-stone', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. Коли камінь видобувають кайлом, який блок зазвичай випадає? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Цегла', 'Гравій', 'Глина', 'Кругляк', 3, 'Зі звичайного каменю зазвичай випадає кругляк, якщо не діють особливі умови на кшталт Шовкового дотику. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 16, false),
  ('glass-is-see-through', 'Сквозь какой блок легко смотреть и хорошо делать окна?', 'Булыжник', 'Терракота', 'Стекло', 'Шерсть', 2, 'Стекло пропускает свет и позволяет видеть наружу, при этом закрывая базу.', 17, true),
  ('obsidian-from-water-and-lava', 'Какой блок образуется, когда вода касается источника лавы?', 'Глина', 'Обсидиан', 'Базальт', 'Кирпичи', 1, 'Источник лавы становится обсидианом, когда на него попадает вода.', 18, true),
  ('planks-build-starter-house', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. У записнику гравця є така польова підказка: Який блок багато гравців виготовляють із колод для початкового будинку? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Дерев''яні дошки', 'Вовняний килим', 'Шибка', 'Редстоуновий пил', 0, 'Дошки — один із перших будівельних матеріалів, які гравці роблять із колод. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 19, false),
  ('sand-falls-with-gravity', 'Какой блок падает вниз, если под ним нет опоры?', 'Дубовые доски', 'Книжная полка', 'Каменные кирпичи', 'Песок', 3, 'Песок является гравитационным блоком, поэтому падает, когда исчезает блок под ним.', 20, true),
  ('coal-fuels-furnace', 'На старті крафт важливий через правильний порядок дій, а не через випадкове натискання рецептів. У записнику гравця є така польова підказка: Який предмет часто використовують як паливо для печі? За цією ситуацією обери рецепт, ресурс або станцію, що дасть потрібний результат.', 'Пісок', 'Вугілля', 'Кругляк', 'Нитка', 1, 'Вугілля використовують саме в такому рецепті, процесі або ремісничій дії. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 21, false),
  ('crafting-table-basics', 'Какой блок чаще всего нужен, чтобы создавать большинство рецептов в Minecraft?', 'Сундук', 'Печь', 'Верстак', 'Кровать', 2, 'Верстак открывает сетку 3x3, поэтому без него недоступны многие важные рецепты.', 22, true),
  ('furnace-smelts-raw-iron', 'Какой блок превращает сырое железо в слитки, если добавить топливо?', 'Бочка', 'Печь', 'Компостер', 'Наковальня', 1, 'Печь переплавляет руды и готовит еду, если в неё положить топливо.', 23, true),
  ('planks-from-logs', 'На старті крафт важливий через правильний порядок дій, а не через випадкове натискання рецептів. Коли гравець майструє з колод на ранній стадії, який базовий будівельний матеріал він зазвичай виготовляє в першу чергу? За цією ситуацією обери рецепт, ресурс або станцію, що дасть потрібний результат.', 'Цегла', 'Дошки', 'Скло', 'Вугілля', 1, 'Такий вибір відповідає рецепту або роботі станції в реальній механіці гри. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 24, false),
  ('sticks-from-planks', 'Какой простой предмет из досок используется во многих рецептах инструментов?', 'Лестница', 'Кнопка', 'Миска', 'Палка', 3, 'Палки являются основным ингредиентом для инструментов, оружия, факелов и многих других рецептов.', 25, true),
  ('carrots-breed-pigs', 'Ферма працює стабільно лише тоді, коли ти знаєш корм, дроп або умови росту без підглядання в рецепт. У записнику гравця є така польова підказка: Який харчовий продукт можна використовувати для розведення свиней? За цією ситуацією обери корм, ресурс, інструмент або умову ферми.', 'Ламінарія', 'Морква', 'Пшениця', 'Гриби', 1, 'Морква є одним із стандартних продуктів для розведення свиней. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 26, false),
  ('chickens-lay-eggs', 'Ферма працює стабільно лише тоді, коли ти знаєш корм, дроп або умови росту без підглядання в рецепт. У записнику гравця є така польова підказка: Який предмет кури відкладають з часом? За цією ситуацією обери корм, ресурс, інструмент або умову ферми.', 'Пір''яні блоки', 'Яйця', 'Молоко', 'Насіння', 1, 'Кури самі відкладають яйця з часом. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 27, false),
  ('cow-drops-leather', 'Какое животное может дать кожу?', 'Корова', 'Треска', 'Кролик', 'Курица', 0, 'Коровы полезны на ферме, потому что могут давать и говядину, и кожу.', 28, true),
  ('sheep-give-wool', 'Ферма працює стабільно лише тоді, коли ти знаєш корм, дроп або умови росту без підглядання в рецепт. У записнику гравця є така польова підказка: Яка сільськогосподарська тварина є звичайним джерелом вовни? За цією ситуацією обери корм, ресурс, інструмент або умову ферми.', 'Кролик', 'Кінь', 'Свиня', 'Вівця', 3, 'Вівці — головне джерело вовни, яку можна зістригати або отримувати як дроп. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 29, false),
  ('wheat-grows-from-seeds', 'Какая культура растёт из семян, которые выпадают из травы?', 'Тыква', 'Кактус', 'Сахарный тростник', 'Пшеница', 3, 'Обычное семечко вырастает в пшеницу, полезную для хлеба, сена и разведения животных.', 30, true),
  ('creeper-explodes', 'Какой враждебный моб известен тем, что шипит и взрывается?', 'Крипер', 'Овца', 'Спрут', 'Корова', 0, 'Криперы опасны, потому что могут подкрасться и взорваться рядом с игроком или постройкой.', 31, true),
  ('large-slime-splits', 'У бою важливо швидко впізнати загрозу за поведінкою моба, а не чекати, поки вона вдарить першою. У записнику гравця є така польова підказка: Що зазвичай відбувається після перемоги над великим слизнем? За цією ситуацією обери моба, предмет або тактику, що відповідає ситуації.', 'Він розпадається на більш дрібні слизи', 'Воно викликає блискавку', 'Випадає шерсть', 'Воно стає повзучим', 0, 'Великі слизні після поразки розпадаються на менших слизнів. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 32, false),
  ('skeleton-uses-bow', 'Какой распространённый враждебный моб обычно атакует из лука?', 'Свинья', 'Скелет', 'Слизень', 'Курица', 1, 'Скелеты атакуют издалека, поэтому укрытие и щит очень помогают против них.', 33, true),
  ('spider-climbs-walls', 'Какой распространённый враждебный моб умеет лазать по стенам?', 'Паук', 'Дельфин', 'Крипер', 'Зомби', 0, 'Пауки могут лазать по вертикальным поверхностям, поэтому простые стены ночью не всегда спасают.', 34, true),
  ('zombies-burn-in-day', 'У бою важливо швидко впізнати загрозу за поведінкою моба, а не чекати, поки вона вдарить першою. У записнику гравця є така польова підказка: Що зазвичай відбувається із зомбі, що стоїть під прямими сонячними променями? За цією ситуацією обери моба, предмет або тактику, що відповідає ситуації.', 'Швидше пливе', 'Це горить', 'Він розмножується', 'Він стає невидимим', 1, 'Зомбі зазвичай згорають під прямим сонцем, якщо їх нічого не захищає. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 35, false),
  ('button-short-redstone-pulse', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який маленький вхідний блок при натисканні зазвичай подає лише короткий редстоун-імпульс? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Книжкова шафа', 'Піч', 'Кнопка', 'Скриня', 2, 'Кнопка подає короткий редстоун-сигнал лише на мить після натискання. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 36, false),
  ('flint-and-steel-lights-portal', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який інструмент найчастіше використовують, щоб запалити портал у Незер? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Кресало', 'Ножиці', 'Компас', 'Підзорна труба', 0, 'Кресалом найчастіше запалюють рамку порталу в Незер. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 37, false),
  ('nether-portal-needs-obsidian', 'Какой блок обычно используют для рамки портала в Незер?', 'Камень', 'Песчаник', 'Обсидиан', 'Медный блок', 2, 'Большинство порталов в Незер строят из обсидиана, потому что он держит рамку портала.', 38, true),
  ('redstone-dust-carries-power', 'Какая пыль переносит редстоун-сигнал между механизмами?', 'Порох', 'Сахар', 'Редстоуновая пыль', 'Пыль светокамня', 2, 'Редстоуновая пыль соединяет переключатели и механизмы, чтобы схема работала.', 39, true),
  ('soul-sand-slows-movement', 'У Незері, Краї та редстоуні помилка швидко коштує ресурсів, тому треба знати базову взаємодію наперед. У записнику гравця є така польова підказка: Який блок сповільнює рух, коли гравець проходить через нього? За цією ситуацією обери компонент, ресурс або правило прогресії, яке спрацює.', 'Гладкий камінь', 'Сухий лід', 'Вугільна руда', 'Пісок душ', 3, 'Пісок душ сповільнює рух і має особливі взаємодії з бульбашковими колонами. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 40, false),
  ('bed-sets-respawn', 'Какой предмет позволяет спать и установить точку возрождения в обычном мире?', 'Лодка', 'Сундук', 'Кровать', 'Флаг', 2, 'Сон в кровати пропускает ночь и обычно устанавливает рядом новую точку возрождения.', 41, true),
  ('cooked-food-better-hunger', 'У перші дні світу важливо не просто знати предмет, а розуміти, коли він рятує темп виживання. У записнику гравця є така польова підказка: Що зазвичай краще втамовує голод, ніж сирий варіант? За цією ситуацією обери дію чи предмет, що справді допоможе вижити.', 'Сніжки', 'Приготована їжа', 'Насіння', 'Дерев''яні інструменти', 1, 'Багато видів їжі після приготування відновлюють голод краще, ніж у сирому вигляді. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 42, false),
  ('eating-refills-hunger', 'Какая шкала пополняется, когда ты ешь еду?', 'Шкала воздуха', 'Шкала голода', 'Шкала опыта', 'Шкала брони', 1, 'Еда заполняет шкалу голода, что помогает спринтовать и восстанавливать здоровье.', 43, true),
  ('shelter-before-first-night', 'У перші дні світу важливо не просто знати предмет, а розуміти, коли він рятує темп виживання. У записнику гравця є така польова підказка: Що варто побудувати для безпеки до настання першої ночі? За цією ситуацією обери дію чи предмет, що справді допоможе вижити.', 'Портал у Незер', 'Укриття', 'Маяк', 'Стіл для чарівництва', 1, 'Просте укриття допомагає пережити першу ніч і сховатися від ворожих мобів. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 44, false),
  ('torch-lights-caves', 'Что игроки часто ставят, чтобы осветить тёмные пещеры?', 'Дверь', 'Седло', 'Факел', 'Ведро', 2, 'Факелы освещают тёмные места, чтобы было лучше видно и безопаснее ходить по пещерам.', 45, true),
  ('armorer-uses-blast-furnace', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Який робочий блок використовує селянин-броняр? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Плавильна піч', 'Картографічний стіл', 'Кафедра', 'Варильна стійка', 0, 'Бронярі використовують плавильні печі як свій робочий блок. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 46, false),
  ('barrel-makes-fisherman', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Яка робоча станція перетворює селянина на рибалку? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Ковадло', 'Каменеріз', 'Компостер', 'Бочка', 3, 'Бочка є робочим блоком рибалки. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 47, false),
  ('bookshelves-boost-enchanting', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Який сусідній блок допомагає столу зачарувань пропонувати сильніші чари? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Бочка', 'Книжкова шафа', 'Ліхтар', 'Мішень', 1, 'Книжкові шафи навколо столу зачарувань підсилюють доступні варіанти чарів. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 48, false),
  ('cartographer-uses-cartography-table', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: На якому робочому блоці працюють картографи? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Стіл лучника', 'Плавильна піч', 'Компостер', 'Картографічний стіл', 3, 'Картографи працюють із картографічним столом. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 49, false),
  ('cauldron-makes-leatherworker', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Який блок допомагає селянину стати шкіряником? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Ткацький верстат', 'Коптильня', 'Казан', 'Бочка', 2, 'Казан найкраще відповідає описаній механіці села або зачарувань. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 50, false),
  ('composter-makes-farmer', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Який блок робочого місця дає селянину професію фермера? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Ткацький верстат', 'Ковадло', 'Коптильня', 'Компостер', 3, 'Компостер є блоком робочого місця, пов’язаним із професією фермера. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 51, false),
  ('emeralds-for-trading', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Який камінь є звичайною валютою в торгівлі селянинами? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Діамант', 'Аметистовий уламок', 'Кварц', 'Смарагд', 3, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 52, false),
  ('fletcher-uses-fletching-table', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. Селянин із яким робочим блоком стає лучником? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Бочка', 'Коптильня', 'Точило', 'Стіл лучника', 3, 'Стіл лучника є блоком робочого місця селянина-лучника. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 53, false),
  ('lapis-for-enchanting', 'Какой синий предмет нужен вместе с опытом, чтобы зачаровать снаряжение на столе?', 'Синий лёд', 'Алмаз', 'Призмарин', 'Лазурит', 3, 'Стол зачарований использует лазурит и уровни опыта для наложения чар.', 54, true),
  ('librarian-sells-books', 'Какая профессия жителя часто продаёт зачарованные книги?', 'Библиотекарь', 'Рыбак', 'Мясник', 'Фермер', 0, 'Библиотекари являются отличными торговцами, когда нужны полезные зачарования.', 55, true),
  ('loom-makes-shepherd', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. Коли селянин береться за ткацький верстат, яка професія з’являється? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Каменяр', 'Мʼясник', 'Вівчар', 'Священник', 2, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 56, false),
  ('nitwit-has-no-profession', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Який селянин не бере нормальної професії? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Лучник', 'Священник', 'Фермер', 'Нездара', 3, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 57, false),
  ('smoker-makes-butcher', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У якому районі села створюється професія м’ясника? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Ткацький верстат', 'Коптильня', 'Дзвін', 'Ковальський стіл', 1, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 58, false),
  ('stonecutter-makes-mason', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Який робочий блок треба поставити, щоб безробітний селянин став майстром каменю? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Каменяр', 'Рибалка', 'Інструментальник', 'Вівчар', 0, 'Це відповідає правилам професій, торгівлі, зачарувань або роботи з досвідом. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 59, false),
  ('villagers-sleep-in-beds', 'У торговому залі й зачаруванні важлива прив’язка до правильного блока або ресурсу, а не схожі назви. У записнику гравця є така польова підказка: Чим зазвичай користуються селяни вночі, коли село нормально працює? За цією ситуацією обери професію, станцію, ресурс або зачарування без плутанини.', 'Ліжка', 'Доменні печі', 'Вогнища', 'Вагонетки', 0, 'Ліжка найкраще відповідає описаній механіці села або зачарувань. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 60, false),
  ('bread-easy-hunger-refill', 'У перші дні світу важливо не просто знати предмет, а розуміти, коли він рятує темп виживання. У записнику гравця є така польова підказка: Яка проста рання їжа добре втамовує голод? За цією ситуацією обери дію чи предмет, що справді допоможе вижити.', 'Кремінь', 'Пісок', 'Перо', 'Хліб', 3, 'Хліб — одна з найпростіших ранніх страв, якою зручно втамовувати голод. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 61, false),
  ('hearts-show-player-health', 'У перші дні світу важливо не просто знати предмет, а розуміти, коли він рятує темп виживання. Які значки на екрані показують запас здоровʼя гравця? За цією ситуацією обери дію чи предмет, що справді допоможе вижити.', 'Значки броні', 'Бульбашки', 'Серця', 'Курячі ніжки', 2, 'Серця показують, скільки здоровʼя зараз має гравець. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 62, false),
  ('armor-cuts-incoming-damage', 'У перші дні світу важливо не просто знати предмет, а розуміти, коли він рятує темп виживання. Коли вас атакують ворожі моби, яке обладнання допомагає зменшити шкоду? За цією ситуацією обери дію чи предмет, що справді допоможе вижити.', 'Сідло', 'Ножиці', 'Компас', 'Обладунки', 3, 'Це рішення напряму впливає на безпеку, відновлення або контроль стартової ситуації. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 63, false),
  ('night-more-hostile-spawns', 'У перші дні світу важливо не просто знати предмет, а розуміти, коли він рятує темп виживання. Після заходу сонця коли ворожі моби починають з’являтися значно частіше? За цією ситуацією обери дію чи предмет, що справді допоможе вижити.', 'Ніч', 'Полудень', 'Ранок', 'Світанок', 0, 'Саме вночі багато ворожих мобів починають з’являтися в темних місцях значно частіше. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 64, false),
  ('door-closes-base-entrance', 'У перші дні світу важливо не просто знати предмет, а розуміти, коли він рятує темп виживання. На вході до стартової бази який простий блок допомагає не пустити моби усередину? За цією ситуацією обери дію чи предмет, що справді допоможе вижити.', 'Квітковий горщик', 'Двері', 'Картина', 'Килим', 1, 'У цій базовій ситуації виживання правильним вибором є Двері. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 65, false),
  ('wool-used-for-bed', 'У перші дні світу важливо не просто знати предмет, а розуміти, коли він рятує темп виживання. Щоб зробити ліжко з дощок, який ще м''який матеріал потрібен? За цією ситуацією обери дію чи предмет, що справді допоможе вижити.', 'Пісок', 'Вовна', 'Глина', 'Папір', 1, 'Вовна найкраще пасує до описаної ситуації раннього виживання. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 66, false),
  ('ladder-climbs-vertical-wall', 'У перші дні світу важливо не просто знати предмет, а розуміти, коли він рятує темп виживання. У записнику гравця є така польова підказка: Що дозволяє гравцеві підніматися прямо вгору по крутій стіні? За цією ситуацією обери дію чи предмет, що справді допоможе вижити.', 'Ліхтар', 'Люк', 'Прапор', 'Драбина', 3, 'Це рішення напряму впливає на безпеку, відновлення або контроль стартової ситуації. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 67, false),
  ('boat-travels-over-water', 'У перші дні світу важливо не просто знати предмет, а розуміти, коли він рятує темп виживання. У записнику гравця є така польова підказка: Який транспортний засіб швидко пересуває гравця по воді через річку чи океан? За цією ситуацією обери дію чи предмет, що справді допоможе вижити.', 'Повідець', 'Вагонетка', 'Човен', 'Сідло', 2, 'У цій базовій ситуації виживання правильним вибором є Човен. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 68, false),
  ('torch-brightens-dark-spaces', 'У перші дні світу важливо не просто знати предмет, а розуміти, коли він рятує темп виживання. У записнику гравця є така польова підказка: Що гравці зазвичай розміщують у темній печері, щоб створити територію світлою? За цією ситуацією обери дію чи предмет, що справді допоможе вижити.', 'Паркан', 'Миска', 'Прапор', 'Смолоскип', 3, 'Смолоскип найкраще пасує до описаної ситуації раннього виживання. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 69, false),
  ('sneaking-prevents-edge-fall', 'У перші дні світу важливо не просто знати предмет, а розуміти, коли він рятує темп виживання. Під час будівництва на висоті, яка рухова дія допоможе вам не зійти з краю? За цією ситуацією обери дію чи предмет, що справді допоможе вижити.', 'Плавання', 'Підкрадається', 'Планерування', 'Спринт', 1, 'Підкрадається найкраще пасує до описаної ситуації раннього виживання. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 70, false),
  ('chest-stores-home-items', 'На старті крафт важливий через правильний порядок дій, а не через випадкове натискання рецептів. У записнику гравця є така польова підказка: Який блок зазвичай створюють на домашній базі для зберігання великої кількості предметів? За цією ситуацією обери рецепт, ресурс або станцію, що дасть потрібний результат.', 'Ліхтар', 'Скриня', 'Ліжко', 'Піч', 1, 'Скриня використовують саме в такому рецепті, процесі або ремісничій дії. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 71, false),
  ('bed-crafted-from-wool-and-planks', 'На старті крафт важливий через правильний порядок дій, а не через випадкове натискання рецептів. У записнику гравця є така польова підказка: Який предмет зроблено з дощок і вовни, щоб спати всю ніч? За цією ситуацією обери рецепт, ресурс або станцію, що дасть потрібний результат.', 'Човен', 'Ліжко', 'Щит', 'Драбина', 1, 'Такий вибір відповідає рецепту або роботі станції в реальній механіці гри. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 72, false),
  ('furnace-crafted-from-cobblestone', 'На старті крафт важливий через правильний порядок дій, а не через випадкове натискання рецептів. У записнику гравця є така польова підказка: Який блок із кільця кругляку використовують для виплавляння? За цією ситуацією обери рецепт, ресурс або станцію, що дасть потрібний результат.', 'Піч', 'Дзвін', 'Бочка', 'Ковадло', 0, 'Піч майструють із кругляку кільцем і використовують для виплавляння. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 73, false),
  ('four-planks-make-crafting-table', 'На старті крафт важливий через правильний порядок дій, а не через випадкове натискання рецептів. Яку робочу станцію створить використання чотирьох дощок у невеликій сітці 2x2? За цією ситуацією обери рецепт, ресурс або станцію, що дасть потрібний результат.', 'Коптильня', 'Верстак', 'Компостер', 'Скриня', 1, 'Такий вибір відповідає рецепту або роботі станції в реальній механіці гри. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 74, false),
  ('planks-work-as-furnace-fuel', 'На старті крафт важливий через правильний порядок дій, а не через випадкове натискання рецептів. Бракує вугілля? Який деревний матеріал ще можна спалити як звичайне піч? За цією ситуацією обери рецепт, ресурс або станцію, що дасть потрібний результат.', 'Дошки', 'Камінь', 'Скло', 'Вовна', 0, 'Такий вибір відповідає рецепту або роботі станції в реальній механіці гри. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 75, false),
  ('pickaxe-breaks-stone-faster', 'На старті крафт важливий через правильний порядок дій, а не через випадкове натискання рецептів. У записнику гравця є така польова підказка: Який інструмент повинен створити гравець, щоб ефективно розбивати камінь і збирати його? За цією ситуацією обери рецепт, ресурс або станцію, що дасть потрібний результат.', 'Ножиці', 'Кайло', 'Мотика', 'Лопата', 1, 'Кайло використовують саме в такому рецепті, процесі або ремісничій дії. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 76, false),
  ('wooden-sword-basic-weapon', 'На старті крафт важливий через правильний порядок дій, а не через випадкове натискання рецептів. Яку базову зброю легко створити з дощок і палиць? За цією ситуацією обери рецепт, ресурс або станцію, що дасть потрібний результат.', 'Дерев''яний меч', 'Тризубець', 'Лук', 'Арбалет', 0, 'Такий вибір відповідає рецепту або роботі станції в реальній механіці гри. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 77, false),
  ('stone-drops-cobblestone', 'На старті крафт важливий через правильний порядок дій, а не через випадкове натискання рецептів. Без Шовкового дотика, що ви зазвичай отримуєте, коли добуєте камінь кайлом? За цією ситуацією обери рецепт, ресурс або станцію, що дасть потрібний результат.', 'Кругляк', 'Гравій', 'Скло', 'Глина', 0, 'Такий вибір відповідає рецепту або роботі станції в реальній механіці гри. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 78, false),
  ('iron-ingots-craft-bucket', 'На старті крафт важливий через правильний порядок дій, а не через випадкове натискання рецептів. У записнику гравця є така польова підказка: Який металевий злиток використовується для створення відра? За цією ситуацією обери рецепт, ресурс або станцію, що дасть потрібний результат.', 'Залізний злиток', 'Незеритовий злиток', 'Золотий злиток', 'Мідний злиток', 0, 'Такий вибір відповідає рецепту або роботі станції в реальній механіці гри. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 79, false),
  ('stone-next-tier-after-wood', 'На старті крафт важливий через правильний порядок дій, а не через випадкове натискання рецептів. На який базовий матеріал для інструментів гравці зазвичай переходять після дерева? За цією ситуацією обери рецепт, ресурс або станцію, що дасть потрібний результат.', 'Пісок', 'Глина', 'Вовна', 'Камінь', 3, 'Після деревʼяних інструментів гравці зазвичай переходять на камʼяні. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 80, false),
  ('logs-turn-into-planks', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. У записнику гравця є така польова підказка: Який блок, зрізаний із дерева, зазвичай спершу перетворюють на дошки? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Вовна', 'Колода', 'Пісок', 'Гравій', 1, 'Колода — це той блок, який зазвичай спершу перетворюють на дошки. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 81, false),
  ('dirt-under-many-grass-blocks', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. У записнику гравця є така польова підказка: Який звичайний природний блок знаходиться під багатьма трав’яними блоками? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Скло', 'Мідь', 'Ґрунт', 'Вовна', 2, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 82, false),
  ('clay-can-be-smelted-into-bricks', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. Зі ставків і річок який м’який блок можна переплавити на цеглу? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Гравій', 'Лід', 'Вугільна руда', 'Глина', 3, 'Глина — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 83, false),
  ('door-swings-open-for-houses', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. Для входу в будинок, який блок відкривається та закривається, як прості ворота? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Плита', 'Двері', 'Смолоскип', 'Килим', 1, 'Двері — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 84, false),
  ('fence-gate-opens-between-fences', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. Через який блок між двома огорожами можуть пройти гравці та тварини? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Ліхтар', 'Ворота паркану', 'Драбина', 'Шибка', 1, 'Ворота паркану — саме той блок чи предмет, що підходить до описаної властивости або будівельної ситуації. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 85, false),
  ('stairs-help-players-climb-builds', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. У записнику гравця є така польова підказка: Який фасонний блок найчастіше використовують, щоб простіше ходити по будівлі? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Килим', 'Сходи', 'Натискна плита', 'Вовна', 1, 'Сходи найкраще пасує до описаної поведінки блока або будівельного використання. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 86, false),
  ('glass-pane-makes-thin-window', 'Під час будівництва блок оцінюють за поведінкою в світі, а не лише за виглядом в інвентарі. У записнику гравця є така польова підказка: Що можуть розмістити гравці для більш тонкого вікна, ніж повні скляні блоки? За цією ситуацією обери блок або будівельну поведінку, яка спрацює в грі.', 'Шибка', 'Ліжко', 'Піч', 'Скриня', 0, 'Поведінка блока в світі збігається з описаною будівельною ситуацією. У питанні перевіряється практичне впізнавання в ігровій ситуації.', 87, false),
